async function rollClashPower(entry,remaining,opponentEntry=null){
  const data=clashData(entry.plan),
        hud=setFloatingClashHud(entry,remaining),
        powerNode=hud?.querySelector('.clash-float-power'),
        container=prepareFloatingClashRoll(entry,remaining),
        unit=combatData[entry.ownerId],
        opponent=opponentEntry?combatData[opponentEntry.ownerId]:null,
        levelBonus=data.grappleCheck?0:clashLevelPowerBonus(unit,opponent),
        attackMod=data.grappleCheck?0:statusAttackPowerModifier(unit),
        clashMod=data.grappleCheck?0:statusClashPowerModifier(unit),
        targetBonus=data.grappleCheck?0:targetFinalPowerVulnerabilityBonus(opponent);

  let power=Math.max(0,data.basePower+data.finalPowerBonus+attackMod+clashMod+levelBonus+targetBonus);
  if(powerNode)powerNode.textContent=power;

  const result=await animateSkillCoinRoll(entry.ownerId,remaining,container,({side:coinSide})=>{
    const paralyzedHead=!data.grappleCheck&&coinSide==='head'&&consumeParalysisOnHead(entry.ownerId);
    if(coinSide==='head'&&!paralyzedHead)power+=data.coinPower;
    if(powerNode)powerNode.textContent=power;
    setFloatingPowerCoinState(entry,coinSide)
  },{attackCoin:!data.grappleCheck});

  setFloatingClashHud(entry,remaining,power,result.coins);
  return{power,heads:result.heads,coins:result.coins}
}

functions.resolveRemainingCoinHits:
async function resolveRemainingCoinHits(entry,targetId,remaining,{heal=false,clashWinner=false}={}){
  const data=clashData(entry.plan),
        target=combatData[targetId];

  if(!target||remaining<=0)return 0;

  const hud=setFloatingClashHud(entry,remaining),
        powerNode=hud?.querySelector('.clash-float-power');

  let currentPower=Math.max(0,data.basePower+data.finalPowerBonus+(entry._counterReaction?(statusDefensePowerModifier(combatData[entry.ownerId])+conditionCounterPowerModifier(combatData[entry.ownerId])):statusAttackPowerModifier(combatData[entry.ownerId]))+targetFinalPowerVulnerabilityBonus(target)),
      total=0,
      resolvedCoins=[];
  const firstCoinIndex=Math.max(0,data.coinAmount-remaining);

  for(let index=0;index<remaining;index++){
    const coinIndex=firstCoinIndex+index;
    setFloatingCoinDetail(hud,data,remaining,coinIndex);
    if(!isUnitTargetable(combatData[targetId]))break;
    const activeStrip=renderFloatingClashCoins(hud,data.coinAmount,remaining,null,{rolling:true});
    if(activeStrip){
      activeStrip.innerHTML=`${resolvedCoins.map(coinResultMarkup).join('')}<span class="clash-current-roll-host"></span>${Array.from({length:Math.max(0,remaining-index-1)},()=>`<span class="clash-float-coin unresolved-tail"><img src="${window.LuminousCoinEngine?.TAIL_SRC||''}" alt="Tail"></span>`).join('')}`
    }

    const container=hud?.querySelector('.clash-current-roll-host');
    if(container){
      container.style.display='flex';
      container.style.alignItems='center'
    }

    let sideResult='tail',
        resolvedCoin=null;

    const result=await animateSkillCoinRoll(entry.ownerId,1,container,({side,src})=>{
      sideResult=side;
      resolvedCoin={side,src};
      setFloatingPowerCoinState(entry,side);
      setFloatingCoinDetail(hud,data,remaining,coinIndex,side)
    });

    resolvedCoin=resolvedCoin||result.coins?.[0]||null;
    resolvedCoins.push(resolvedCoin);

    const paralyzedHead=sideResult==='head'&&consumeParalysisOnHead(entry.ownerId);
    if(sideResult==='head'&&!paralyzedHead)currentPower+=data.coinPower;

    const hit=Math.max(0,currentPower);

    if(powerNode)powerNode.textContent=hit;

    renderFloatingClashCoins(
      hud,
      data.coinAmount,
      remaining,
      resolvedCoins.concat(
        Array.from({length:Math.max(0,remaining-resolvedCoins.length)},()=>null)
      )
    );

    // Evade is a reactive Defense Skill, not a normal Clash. The defender rolls
    // a fresh Evade Coin against EACH incoming Attack Coin. Ties belong to Evade:
    // only Attack Power strictly greater than Evade Power lands a Hit.
    if(!heal){
      const evadeResult=await resolveEvadeAgainstCoin(targetId,hit,entry,{coinIndex,side:sideResult});
      if(evadeResult?.evaded){
        setFloatingClashResult(entry,`EVADED · ${hit} ≤ ${evadeResult.power}`,'tie');
        await wait(COMBAT_PACE.hitGap);
        continue
      }
    }

    if(!heal){
      // Every confirmed Hit has physical choreography. Melee advances while the
      // defender recoils; Range stays planted and only drives the target back.
      await animateHitMotion(entry,targetId)
    }

    if(heal){
      total+=hit;
      healCombatant(targetId,hit)
    }else{
      const damageResult=damageCombatant(targetId,hit,{damageType:data.damageType,attackerId:entry.ownerId,skillData:entry.plan?.data}),
            finalHit=Number(damageResult?.finalDamage)||0;
      total+=finalHit;
      // Existing hit-reactive statuses resolve BEFORE new statuses from this
      // Coin are inflicted, matching the repository Skill Effect ordering.
      triggerGettingHitStatuses(targetId,entry);
      if(damageResult?.critical)applySkillStatusEffects(entry,targetId,'[On Crit]',{coinIndex,side:sideResult,damageResult});
      if(entry.plan?.data?.tremorBurst)triggerTremorBurst(targetId,entry.ownerId)
    }

    if(!heal){
      applySkillStatusEffects(entry,targetId,'[On Hit]',{coinIndex,side:sideResult});
      applySkillStatusEffects(entry,targetId,sideResult==='head'?'[Heads Hit]':'[Tails Hit]',{coinIndex,side:sideResult});
      // Counter reacts immediately after a completed Hit. Exactly one armed
      // Counter Action Slot is consumed per Hit; extra Counter Slots remain for
      // later Hits in the same Turn.
      await triggerCounterAfterHit(targetId,entry.ownerId,entry);
      if(!isUnitTargetable(combatData[entry.ownerId]))break
    }

    // No HIT / TOTAL DAMAGE text over the unit. The target receives only the
    // numeric damage popup plus its Slash / Pierce / Blunt icon.
    await wait(COMBAT_PACE.hitGap)
  }

  await wait(COMBAT_PACE.totalHold);
  return total
}

functions.resolveSkillClash:
async function resolveSkillClash(entryA,entryB){
  const dataA=clashData(entryA.plan),
        dataB=clashData(entryB.plan),
        totalA=dataA.coinAmount,
        totalB=dataB.coinAmount;

  processConditionRemovalTrigger(entryA.ownerId,'attack');
  processConditionRemovalTrigger(entryB.ownerId,'attack');
  markEntryStarted(entryA);
  markEntryStarted(entryB);

  // Both Units physically enter the clash point.
  moveClashUnitsToMidpoint(entryA,entryB);

  let remainingA=totalA,
      remainingB=totalB,
      clashCount=0;

  setFloatingClashHud(entryA,remainingA);
  setFloatingClashHud(entryB,remainingB);
  await wait(COMBAT_PACE.clashApproach);

  // Automatic clash loop. No player input until one side runs out of Coins.
  while(remainingA>0&&remainingB>0){
    clashCount++;

    showClashCount(entryA,entryB,clashCount);

    // CONTACT -> SPARK -> roll/result. This is the shared FX hook for melee,
    // mixed Range/Melee and Range/Range Clashes.
    await animateClashContact(entryA,entryB);

    const [rollA,rollB]=await Promise.all([
      rollClashPower(entryA,remainingA,entryB),
      rollClashPower(entryB,remainingB,entryA)
    ]);

    setFloatingClashHud(entryA,remainingA,rollA.power,rollA.coins);
    setFloatingClashHud(entryB,remainingB,rollB.power,rollB.coins);

    if(rollA.power===rollB.power){
      await animateClashOutcome(entryA,entryB,'tie');
      await wait(COMBAT_PACE.tieResult);
      continue
    }

    if(rollA.power>rollB.power){
      remainingB--;
      // Losing Coins are consumed from the left visually.
      setFloatingClashHud(entryB,remainingB,rollB.power,rollB.coins);
      await animateClashOutcome(entryA,entryB,'a')
    }else{
      remainingA--;
      setFloatingClashHud(entryA,remainingA,rollA.power,rollA.coins);
      await animateClashOutcome(entryA,entryB,'b')
    }

    await wait(COMBAT_PACE.clashResult)
  }

  const winner=remainingA>0?entryA:entryB,
        loser=winner===entryA?entryB:entryA,
        remaining=winner===entryA?remainingA:remainingB,
        spGain=10+clashCount;

  // Skill outcome triggers resolve once, after the Clash winner is known and
  // before surviving Coins begin their hit sequence.
  applySkillStatusEffects(winner,loser.ownerId,'[Clash Win]',{clashCount});
  applySkillStatusEffects(loser,winner.ownerId,'[Clash Lose]',{clashCount});

  healCombatantSP(winner.ownerId,spGain);
  await wait(COMBAT_PACE.spAward);

  // The final Clash loss has a stronger physical consequence. A melee winner
  // closes to striking range; a ranged winner keeps firing position and knocks
  // the melee loser farther away.
  await animateClashDefeat(winner,loser);

  // Loser HUD goes away; winner keeps its floating HUD for the surviving hits.
  closeFloatingClashHud(loser);
  await resolveRemainingCoinHits(
    winner,
    loser.ownerId,
    remaining,
    {heal:false,clashWinner:true}
  );

  await wait(250);
  closeFloatingClashHud(winner);
  hideClashCount(entryA,entryB);
  settleClashUnits(entryA,entryB);
  await wait(COMBAT_PACE.returnFromClash);

  return{winner,loser,clashCount,spGain,remaining}
}

functions.resolveEvadeAgainstCoin:
async function resolveEvadeAgainstCoin(defenderId,attackPower,attackerEntry,{coinIndex=0,side='tail'}={}){
  const defender=combatData[defenderId],state=defender?.reactiveDefense,
        armed=state?.turn===round?state.evade:null;
  if(!armed?.active)return{evaded:false,active:false};
  if(unitReactionBlocked(defender)){
    disarmEvade(defenderId,{broken:true});
    return{evaded:false,active:false,blocked:true}
  }
  const entry=armed.entry,
        data=entry?.plan?.data||{},
        base=Math.max(0,(Number(data.basePower)||0)+(Number(entry?.plan?._helpFinalPowerBonus)||0)+statusDefensePowerModifier(defender)+conditionEvasionPowerModifier(defender)),
        coinPower=Number(data.coinPower)||0,
        hud=setFloatingClashHud(entry,1),
        powerNode=hud?.querySelector('.clash-float-power'),
        container=prepareFloatingClashRoll(entry,1);
  if(!hud||!container)return{evaded:false,active:true};
  setFloatingClashResult(entry,'EVADE · REACTIVE','shield');
  if(powerNode)powerNode.textContent=base;
  let evadeSide='tail';
  const result=await animateSkillCoinRoll(defenderId,1,container,({side:rolledSide})=>{
    evadeSide=rolledSide;
    setFloatingPowerCoinState(entry,rolledSide)
  },{attackCoin:false});
  const paralyzedHead=evadeSide==='head'&&consumeParalysisOnHead(defenderId),
        evadePower=Math.max(0,base+(evadeSide==='head'&&!paralyzedHead?coinPower:0)),
        evaded=Number(attackPower)<=evadePower;
  setFloatingClashHud(entry,1,evadePower,result.coins);
  setFloatingClashResult(entry,evaded?`EVADE ${evadePower} · SUCCESS`:`EVADE ${evadePower} · BROKEN`,evaded?'shield':'lose');
  if(evaded){
    applySkillStatusEffects(entry,attackerEntry?.ownerId,'[On Evade]',{coinIndex,side});
    await wait(280);
    closeFloatingClashHud(entry);
    return{evaded:true,active:true,power:evadePower,side:evadeSide}
  }
  disarmEvade(defenderId,{broken:true});
  await wait(280);
  closeFloatingClashHud(entry);
  return{evaded:false,active:false,broken:true,power:evadePower,side:evadeSide}
}

functions.resolveGuardAction:
async function resolveGuardAction(entry){
  const data=entry?.plan?.data||{},
        base=Math.max(0,(Number(data.basePower)||0)+(Number(entry?.plan?._helpFinalPowerBonus)||0)+statusDefensePowerModifier(combatData[entry.ownerId])),
        coinPower=Number(data.coinPower)||0,
        coinCount=1,
        hud=setFloatingClashHud(entry,coinCount),
        powerNode=hud?.querySelector('.clash-float-power'),
        container=prepareFloatingClashRoll(entry,coinCount);

  if(!hud||!container)return 0;
  setFloatingClashResult(entry,'GUARD · EPHEMERAL SHIELD','shield');
  if(powerNode)powerNode.textContent=base;

  let sideResult='tail';
  const result=await animateSkillCoinRoll(entry.ownerId,coinCount,container,({side})=>{
    sideResult=side;
    setFloatingPowerCoinState(entry,side)
  },{attackCoin:false});

  const shieldAmount=Math.max(0,base+(sideResult==='head'?coinPower:0));
  setFloatingClashHud(entry,coinCount,shieldAmount,result.coins);
  addEphemeralShield(entry.ownerId,shieldAmount);
  setFloatingClashResult(entry,`${sideResult.toUpperCase()} · SHIELD +${shieldAmount}`,'shield');
  await wait(COMBAT_PACE.totalHold);
  closeFloatingClashHud(entry);
  return shieldAmount
}

functions.resolveSaveOnlySpell:
async function resolveSaveOnlySpell(entry){
  const plan=entry?.plan,data=plan?.data||{};
  if(!entry||!plan||!data.save)return null;
  markEntryStarted(entry);
  const targets=planTargetUnitIds(plan,entry.ownerId),needsConcentration=Boolean(data.concentration||(data.failedSaveEffects||[]).some(effect=>String(effect?.durationType||'').toLowerCase()==='concentration')),
        conc=needsConcentration?ensureEntryConcentration(entry):null,results=[];
  setStatus(`SPELL · ${data.name||'Magic'} · ${saveAbilityLabel(data.save.ability)} SAVE ${Math.max(0,Number(data.save.threshold)||0)}${needsConcentration?' · CONCENTRATION':''}`);
  await wait(180);
  for(const targetId of targets){
    if(!isUnitTargetable(combatData[targetId]))continue;
    const result=resolveSaveEffect(entry.ownerId,targetId,data.save,data.failedSaveEffects||[],{
      sourceType:'magic',sourceElement:normalizeElement(data.element||''),concentrationId:conc?.id||null,sourceLabel:data.name||'Magic',detectThreshold:data.detectThreshold??data.save.threshold
    });
    results.push({targetId,result});
    await wait(260)
  }
  return results
}
